// amplify/auth/pre-sign-up/handler.ts
import type { PreSignUpTriggerHandler } from 'aws-lambda';

const normalizeRole = (r?: string) => {
  const v = (r || '').trim().toLowerCase();
  if (v === 'owner') return 'Owner';
  if (v === 'member') return 'Member';
  return undefined;
};

export const handler: PreSignUpTriggerHandler = async (event) => {
  // Only run for native self sign-up
  if (event.triggerSource !== 'PreSignUp_SignUp') return event;

  // Prefer custom attribute (what your client sends), fall back to clientMetadata
  const incoming =
    event.request.userAttributes['custom:role'] ||
    event.request.clientMetadata?.role;

  const role = normalizeRole(incoming);
  if (!role) {
    // You can change this to default('Owner') if you truly want a default
    throw new Error("Invalid role. 'custom:role' must be 'Owner' or 'Member'.");
  }

  // Stamp the normalized/validated value
  event.request.userAttributes['custom:role'] = role;

  // Optional: auto-confirm or auto-verify email here if desired
  // event.response.autoConfirmUser = true;
  // event.response.autoVerifyEmail = true;

  return event;
};
